const stack = (cur) => `## Stack
${[[13,'Fix steering-vector docs and validate estimator inputs','main'],[14,'Add runtime benchmark against pyMUSIC','#13']].map(([n,t,b])=>`- ${n===cur?'👉 ':''}#${n} ${t} (base: ${b})`).join('\n')}

Merge from the bottom up: #13 into \`main\`, then retarget #14 to \`main\`.

`;
const b13 = await $`gh pr view 13 --json body -q .body`.text();
const b14 = await $`gh pr view 14 --json body -q .body`.text();
const nb13 = stack(13) + b13.trim();
const nb14 = stack(14) + b14.trim().replace(" Stacked on #13; I'll retarget it to `main` once #13 is merged.", '');
await $`gh pr edit 13 --body ${nb13}`;
await $`gh pr edit 14 --body ${nb14} --title ${"[2/2] Add runtime benchmark against pyMUSIC"}`;
await $`gh pr edit 13 --title ${"[1/2] Fix steering-vector docs and validate estimator inputs"}`;
await $`gh pr view 14 --json title,baseRefName,body -q '.title + " -> " + .baseRefName + "\n" + (.body|split("\n")[0:8]|join("\n"))'`.text()

